n=17; m=n//2
out=[]
for r in range(n):
    row=[0]*n
    if r<=m:
        for c in {m-r,m+r}: row[c]=2
    if r>=3:
        for c in range(n):
            if (c-r)%4==2 and row[c]==0: row[c]=1
    out.append(row)
out

